package cloud.trotter.feed.contract

import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.JsonPrimitive
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.ByteArrayInputStream

/**
 * The cross-language vector (#1564): a fuel generation signed by the Python publisher (`tools/feeds/publish_fuel.py`,
 * regenerated by `tools/feeds/make_vector.py` with an ephemeral key) verifies here, through the same user-pin path a
 * self-hosted feed takes, and a copy of its envelope with one byte changed is refused.
 */
class PublisherVectorTest {

    private fun resource(name: String): ByteArray =
        requireNotNull(javaClass.getResourceAsStream("/vectors/fuel/$name")) { "missing vector file $name" }
            .use { it.readBytes() }

    private val publicKey = String(resource("public-key.txt")).trim()
    private val source = requireNotNull(FeedKeys.customSourceId(publicKey))
    private val trust = (FeedTrust.shipped(listOf(UserPin(Feed.FUEL, publicKey))) as FeedResult.Ok).value

    @Test
    fun `the publisher's envelope and payload verify`() {
        val manifest = (VerifiedManifest.verify(trust, source, Feed.FUEL, ByteArrayInputStream(resource("envelope.json")))
            as FeedResult.Ok).value
        assertEquals(1794938400000L, manifest.sequence)
        assertEquals(manifest.sequence, manifest.issuedAt)
        assertEquals(1L, manifest.contract)

        val entry = FeedFiles.select(manifest) { false }.single()
        assertEquals("prices", entry.name)
        val file = (VerifiedFeedFile.verify(manifest, entry.name, ByteArrayInputStream(resource("${entry.sha256}.json")))
            as FeedResult.Ok).value
        val payload = (FeedFiles.parsePayload(file) as FeedResult.Ok).value as JsonObject
        assertEquals(JsonPrimitive("EIA"), payload["source"])
        assertEquals(JsonPrimitive(3.051), (payload["prices"] as JsonObject)["NUS"].let { (it as JsonObject)["regular"] })
    }

    @Test
    fun `the envelope with one byte changed is refused`() {
        val good = resource("envelope.json")
        val changed = resource("envelope-one-byte-changed.json")
        assertEquals(good.size, changed.size)
        assertEquals(1, good.indices.count { good[it] != changed[it] })
        val result = VerifiedManifest.verify(trust, source, Feed.FUEL, ByteArrayInputStream(changed))
        assertEquals(FeedRefusal.BadSignature, (result as FeedResult.Refused).reason)
    }

    @Test
    fun `the payload with one byte changed is refused`() {
        val manifest = (VerifiedManifest.verify(trust, source, Feed.FUEL, ByteArrayInputStream(resource("envelope.json")))
            as FeedResult.Ok).value
        val entry = manifest.files.single()
        val bytes = resource("${entry.sha256}.json").copyOf()
        bytes[bytes.size / 2] = (bytes[bytes.size / 2].toInt() xor 0x01).toByte()
        val result = VerifiedFeedFile.verify(manifest, entry.name, ByteArrayInputStream(bytes))
        assertTrue(result is FeedResult.Refused)
        assertEquals(FeedRefusal.HashMismatch, (result as FeedResult.Refused).reason)
    }
}
